using System;using System.Configuration;using System.Data;using System.Data.SqlClient;using AshkanJobCenter.Core;namespace AshkanJobCenter.Data{public static class Database{static string DbName=>ConfigurationManager.AppSettings["DatabaseName"]??"AshkanJobCenterDB";public static string Master=>@"Data Source=(LocalDB)\MSSQLLocalDB;Initial Catalog=master;Integrated Security=True;Connect Timeout=15";public static string Conn=>@"Data Source=(LocalDB)\MSSQLLocalDB;Initial Catalog="+DbName+@";Integrated Security=True;Connect Timeout=15;MultipleActiveResultSets=True";public static void Initialize(){using(var c=new SqlConnection(Master)){c.Open();using(var cmd=new SqlCommand("IF DB_ID(@n) IS NULL EXEC('CREATE DATABASE ["+DbName.Replace("]","]]" )+"]')",c)){cmd.Parameters.AddWithValue("@n",DbName);cmd.ExecuteNonQuery();}}using(var c=new SqlConnection(Conn)){c.Open();string sql=@"
IF OBJECT_ID('Users') IS NULL CREATE TABLE Users(Id INT IDENTITY PRIMARY KEY,Username NVARCHAR(80) NOT NULL UNIQUE,PasswordHash NVARCHAR(200) NOT NULL,Salt NVARCHAR(100) NOT NULL,FullName NVARCHAR(150) NOT NULL,Email NVARCHAR(150),Role NVARCHAR(30) NOT NULL,IsActive BIT NOT NULL DEFAULT 1,CreatedAt DATETIME2 NOT NULL DEFAULT SYSDATETIME());
IF OBJECT_ID('Companies') IS NULL CREATE TABLE Companies(Id INT IDENTITY PRIMARY KEY,Name NVARCHAR(180) NOT NULL,Industry NVARCHAR(120),City NVARCHAR(100),Phone NVARCHAR(50),Email NVARCHAR(150),Website NVARCHAR(200),IsActive BIT NOT NULL DEFAULT 1,CreatedAt DATETIME2 DEFAULT SYSDATETIME());
IF OBJECT_ID('Jobs') IS NULL CREATE TABLE Jobs(Id INT IDENTITY PRIMARY KEY,Title NVARCHAR(180) NOT NULL,CompanyId INT NULL,Category NVARCHAR(120),City NVARCHAR(100),EmploymentType NVARCHAR(60),SalaryMin DECIMAL(18,0) NULL,SalaryMax DECIMAL(18,0) NULL,Description NVARCHAR(MAX),Status NVARCHAR(30) NOT NULL DEFAULT 'Open',CreatedAt DATETIME2 DEFAULT SYSDATETIME(),FOREIGN KEY(CompanyId) REFERENCES Companies(Id));
IF OBJECT_ID('Candidates') IS NULL CREATE TABLE Candidates(Id INT IDENTITY PRIMARY KEY,FullName NVARCHAR(160) NOT NULL,NationalCode NVARCHAR(30),Mobile NVARCHAR(50),Email NVARCHAR(150),City NVARCHAR(100),Education NVARCHAR(120),PrimarySkill NVARCHAR(160),ExperienceYears INT DEFAULT 0,Status NVARCHAR(40) DEFAULT 'Available',CreatedAt DATETIME2 DEFAULT SYSDATETIME());
IF OBJECT_ID('Applications') IS NULL CREATE TABLE Applications(Id INT IDENTITY PRIMARY KEY,JobId INT NOT NULL,CandidateId INT NOT NULL,Stage NVARCHAR(50) NOT NULL DEFAULT 'Applied',Score INT NULL,Notes NVARCHAR(MAX),AppliedAt DATETIME2 DEFAULT SYSDATETIME(),FOREIGN KEY(JobId) REFERENCES Jobs(Id),FOREIGN KEY(CandidateId) REFERENCES Candidates(Id));
IF OBJECT_ID('AuditLog') IS NULL CREATE TABLE AuditLog(Id BIGINT IDENTITY PRIMARY KEY,UserId INT NULL,Action NVARCHAR(100),Entity NVARCHAR(80),Details NVARCHAR(500),CreatedAt DATETIME2 DEFAULT SYSDATETIME());
IF OBJECT_ID('CandidateSkills') IS NULL CREATE TABLE CandidateSkills(Id INT IDENTITY PRIMARY KEY,CandidateId INT NOT NULL,Skill NVARCHAR(120) NOT NULL,Level NVARCHAR(30),Years INT DEFAULT 0,FOREIGN KEY(CandidateId) REFERENCES Candidates(Id));
IF OBJECT_ID('Interviews') IS NULL CREATE TABLE Interviews(Id INT IDENTITY PRIMARY KEY,ApplicationId INT NOT NULL,ScheduledAt DATETIME2 NOT NULL,InterviewType NVARCHAR(40),Location NVARCHAR(250),Interviewer NVARCHAR(150),Status NVARCHAR(40) DEFAULT 'Scheduled',Notes NVARCHAR(MAX),CreatedAt DATETIME2 DEFAULT SYSDATETIME(),FOREIGN KEY(ApplicationId) REFERENCES Applications(Id));
IF OBJECT_ID('Notifications') IS NULL CREATE TABLE Notifications(Id BIGINT IDENTITY PRIMARY KEY,UserId INT NULL,Title NVARCHAR(180) NOT NULL,Message NVARCHAR(600),IsRead BIT NOT NULL DEFAULT 0,CreatedAt DATETIME2 DEFAULT SYSDATETIME());
IF OBJECT_ID('Favorites') IS NULL CREATE TABLE Favorites(Id INT IDENTITY PRIMARY KEY,UserId INT NOT NULL,EntityType NVARCHAR(30) NOT NULL,EntityId INT NOT NULL,CreatedAt DATETIME2 DEFAULT SYSDATETIME());
IF COL_LENGTH('Candidates','LinkedIn') IS NULL ALTER TABLE Candidates ADD LinkedIn NVARCHAR(250) NULL;
IF COL_LENGTH('Candidates','ResumePath') IS NULL ALTER TABLE Candidates ADD ResumePath NVARCHAR(500) NULL;
IF OBJECT_ID('Offers') IS NULL CREATE TABLE Offers(Id INT IDENTITY PRIMARY KEY,ApplicationId INT NOT NULL,Salary DECIMAL(18,0) NULL,StartDate DATE NULL,ExpiryDate DATE NULL,Status NVARCHAR(30) NOT NULL DEFAULT 'Draft',CreatedBy INT NULL,CreatedAt DATETIME2 DEFAULT SYSDATETIME(),FOREIGN KEY(ApplicationId) REFERENCES Applications(Id));
IF OBJECT_ID('InterviewScorecards') IS NULL CREATE TABLE InterviewScorecards(Id INT IDENTITY PRIMARY KEY,InterviewId INT NOT NULL,TechnicalScore INT,CommunicationScore INT,CultureScore INT,Recommendation NVARCHAR(30),Comments NVARCHAR(1000),CreatedBy INT NULL,CreatedAt DATETIME2 DEFAULT SYSDATETIME(),FOREIGN KEY(InterviewId) REFERENCES Interviews(Id));
IF OBJECT_ID('SavedSearches') IS NULL CREATE TABLE SavedSearches(Id INT IDENTITY PRIMARY KEY,UserId INT NOT NULL,Name NVARCHAR(120) NOT NULL,EntityType NVARCHAR(30),QueryText NVARCHAR(500),CreatedAt DATETIME2 DEFAULT SYSDATETIME());
IF OBJECT_ID('CandidateTags') IS NULL CREATE TABLE CandidateTags(Id INT IDENTITY PRIMARY KEY,CandidateId INT NOT NULL,Tag NVARCHAR(80) NOT NULL,CreatedAt DATETIME2 DEFAULT SYSDATETIME(),FOREIGN KEY(CandidateId) REFERENCES Candidates(Id));
IF OBJECT_ID('CandidateNotes') IS NULL CREATE TABLE CandidateNotes(Id INT IDENTITY PRIMARY KEY,CandidateId INT NOT NULL,UserId INT NULL,Note NVARCHAR(1500) NOT NULL,CreatedAt DATETIME2 DEFAULT SYSDATETIME(),FOREIGN KEY(CandidateId) REFERENCES Candidates(Id));
IF COL_LENGTH('Candidates','Summary') IS NULL ALTER TABLE Candidates ADD Summary NVARCHAR(1000) NULL;
IF OBJECT_ID('RolePermissions') IS NULL CREATE TABLE RolePermissions(Id INT IDENTITY PRIMARY KEY,RoleName NVARCHAR(30) NOT NULL,PermissionKey NVARCHAR(100) NOT NULL,IsAllowed BIT NOT NULL DEFAULT 1,CONSTRAINT UQ_RolePermission UNIQUE(RoleName,PermissionKey));
IF OBJECT_ID('FeatureFlags') IS NULL CREATE TABLE FeatureFlags(Id INT IDENTITY PRIMARY KEY,FeatureKey NVARCHAR(100) NOT NULL UNIQUE,IsEnabled BIT NOT NULL DEFAULT 1,Description NVARCHAR(300));
IF OBJECT_ID('EmailTemplates') IS NULL CREATE TABLE EmailTemplates(Id INT IDENTITY PRIMARY KEY,Name NVARCHAR(120) NOT NULL,Subject NVARCHAR(250),Body NVARCHAR(MAX),IsActive BIT NOT NULL DEFAULT 1,CreatedAt DATETIME2 DEFAULT SYSDATETIME());
IF OBJECT_ID('JobAlerts') IS NULL CREATE TABLE JobAlerts(Id INT IDENTITY PRIMARY KEY,UserId INT NOT NULL,Keyword NVARCHAR(150) NOT NULL,City NVARCHAR(100),Frequency NVARCHAR(20) NOT NULL DEFAULT 'Daily',IsActive BIT NOT NULL DEFAULT 1,CreatedAt DATETIME2 DEFAULT SYSDATETIME());
IF OBJECT_ID('CandidateDocuments') IS NULL CREATE TABLE CandidateDocuments(Id INT IDENTITY PRIMARY KEY,CandidateId INT NOT NULL,Title NVARCHAR(150),FilePath NVARCHAR(500),DocumentType NVARCHAR(60),CreatedAt DATETIME2 DEFAULT SYSDATETIME(),FOREIGN KEY(CandidateId) REFERENCES Candidates(Id));
IF OBJECT_ID('TalentPoolMembers') IS NULL CREATE TABLE TalentPoolMembers(Id INT IDENTITY PRIMARY KEY,CandidateId INT NOT NULL,PoolStatus NVARCHAR(30) NOT NULL DEFAULT 'Warm',Source NVARCHAR(120),Notes NVARCHAR(1000),AddedBy INT NULL,CreatedAt DATETIME2 DEFAULT SYSDATETIME(),CONSTRAINT UQ_TalentPoolCandidate UNIQUE(CandidateId),FOREIGN KEY(CandidateId) REFERENCES Candidates(Id));
IF NOT EXISTS(SELECT 1 FROM sys.indexes WHERE name='IX_TalentPool_Status') CREATE INDEX IX_TalentPool_Status ON TalentPoolMembers(PoolStatus,CreatedAt);
IF OBJECT_ID('RecruitmentTasks') IS NULL CREATE TABLE RecruitmentTasks(Id INT IDENTITY PRIMARY KEY,Title NVARCHAR(180) NOT NULL,CandidateId INT NULL,AssignedTo INT NULL,Priority NVARCHAR(20) NOT NULL DEFAULT 'Medium',DueAt DATETIME2 NULL,IsCompleted BIT NOT NULL DEFAULT 0,CompletedAt DATETIME2 NULL,CreatedAt DATETIME2 DEFAULT SYSDATETIME(),FOREIGN KEY(CandidateId) REFERENCES Candidates(Id));
IF NOT EXISTS(SELECT 1 FROM sys.indexes WHERE name='IX_RecruitmentTasks_Assignee') CREATE INDEX IX_RecruitmentTasks_Assignee ON RecruitmentTasks(AssignedTo,IsCompleted,DueAt);
IF NOT EXISTS(SELECT 1 FROM sys.indexes WHERE name='IX_Applications_CandidateStage') CREATE INDEX IX_Applications_CandidateStage ON Applications(CandidateId,Stage);
IF NOT EXISTS(SELECT 1 FROM sys.indexes WHERE name='IX_Interviews_ScheduledAt') CREATE INDEX IX_Interviews_ScheduledAt ON Interviews(ScheduledAt,Status);
IF NOT EXISTS(SELECT 1 FROM sys.indexes WHERE name='IX_Applications_Stage') CREATE INDEX IX_Applications_Stage ON Applications(Stage);
IF NOT EXISTS(SELECT 1 FROM sys.indexes WHERE name='IX_Candidates_Status') CREATE INDEX IX_Candidates_Status ON Candidates(Status);
IF NOT EXISTS(SELECT 1 FROM sys.indexes WHERE name='IX_Favorites_UserEntity') CREATE INDEX IX_Favorites_UserEntity ON Favorites(UserId,EntityType,EntityId);
IF NOT EXISTS(SELECT 1 FROM sys.indexes WHERE name='IX_JobAlerts_User') CREATE INDEX IX_JobAlerts_User ON JobAlerts(UserId,IsActive);
IF NOT EXISTS(SELECT 1 FROM FeatureFlags WHERE FeatureKey='AdvancedSearch') INSERT FeatureFlags(FeatureKey,IsEnabled,Description) VALUES('AdvancedSearch',1,'Advanced cross-module search');
IF NOT EXISTS(SELECT 1 FROM FeatureFlags WHERE FeatureKey='Reports') INSERT FeatureFlags(FeatureKey,IsEnabled,Description) VALUES('Reports',1,'Operational reports and CSV export');";new SqlCommand(sql,c).ExecuteNonQuery();using(var count=new SqlCommand("SELECT COUNT(*) FROM Users",c)){if((int)count.ExecuteScalar()==0){var salt=Security.Salt();var hash=Security.Hash("Admin@123",salt);using(var cmd=new SqlCommand("INSERT Users(Username,PasswordHash,Salt,FullName,Email,Role) VALUES(@u,@p,@s,@f,@e,'Admin')",c)){cmd.Parameters.AddWithValue("@u","admin");cmd.Parameters.AddWithValue("@p",hash);cmd.Parameters.AddWithValue("@s",salt);cmd.Parameters.AddWithValue("@f","System Administrator");cmd.Parameters.AddWithValue("@e","admin@local");cmd.ExecuteNonQuery();}Seed(c);}}}}
static void Seed(SqlConnection c){new SqlCommand("INSERT Companies(Name,Industry,City,Email) VALUES(N'شرکت نمونه فناوری',N'فناوری اطلاعات',N'تهران','hr@example.local'),(N'صنایع نمونه',N'صنعت',N'کرج','jobs@example.local'); INSERT Jobs(Title,CompanyId,Category,City,EmploymentType,Description) VALUES(N'توسعه‌دهنده نرم‌افزار',1,N'نرم‌افزار',N'تهران',N'تمام وقت',N'توسعه و نگهداری نرم‌افزار'),(N'کارشناس پشتیبانی',2,N'پشتیبانی',N'کرج',N'تمام وقت',N'پشتیبانی کاربران'); INSERT Candidates(FullName,Mobile,Email,City,Education,PrimarySkill,ExperienceYears) VALUES(N'کارجوی نمونه','09120000000','candidate@example.local',N'تهران',N'کارشناسی',N'C# / SQL Server',3);",c).ExecuteNonQuery();}
public static DataTable Query(string sql,params SqlParameter[] ps){using(var c=new SqlConnection(Conn))using(var cmd=new SqlCommand(sql,c)){if(ps!=null)cmd.Parameters.AddRange(ps);var t=new DataTable();c.Open();t.Load(cmd.ExecuteReader());return t;}}public static int Exec(string sql,params SqlParameter[] ps){using(var c=new SqlConnection(Conn))using(var cmd=new SqlCommand(sql,c)){if(ps!=null)cmd.Parameters.AddRange(ps);c.Open();return cmd.ExecuteNonQuery();}}public static object Scalar(string sql,params SqlParameter[] ps){using(var c=new SqlConnection(Conn))using(var cmd=new SqlCommand(sql,c)){if(ps!=null)cmd.Parameters.AddRange(ps);c.Open();return cmd.ExecuteScalar();}}public static void Audit(string action,string entity,string details){try{Exec("INSERT AuditLog(UserId,Action,Entity,Details) VALUES(@u,@a,@e,@d)",new SqlParameter("@u",AppSession.UserId==0?(object)DBNull.Value:AppSession.UserId),new SqlParameter("@a",action),new SqlParameter("@e",entity),new SqlParameter("@d",details??""));}catch{}}}}